pragma solidity 0.8.35;

/// @notice The configuration of a Morpho Blue market
/// @dev Mirrors the struct of the canonical Morpho Blue deployment; the
/// market id is keccak256(abi.encode(marketParams))
struct MarketParams {
    address loanToken;
    address collateralToken;
    address oracle;
    address irm;
    uint256 lltv;
}

/// @title IMorpho - Minimal Morpho Blue Interface
/// @author Sivo
/// @notice The subset of Morpho Blue used by the Multiplier: fee-free flash
/// loans, collateral supply, and borrowing on behalf of an authorized user
interface IMorpho {
    /// @notice Executes a fee-free flash loan of `assets` of `token`
    /// @dev Calls onMorphoFlashLoan on the caller, then pulls the same amount
    /// back via transferFrom (requires a prior approval)
    /// @param token The token to flash loan
    /// @param assets The amount to flash loan
    /// @param data Arbitrary data passed through to the callback
    function flashLoan(
        address token,
        uint256 assets,
        bytes calldata data
    ) external;

    /// @notice Supplies collateral on behalf of `onBehalf`
    /// @dev Pulls the collateral from the caller; supplying on behalf of any
    /// address requires no authorization
    /// @param marketParams The market to supply collateral to
    /// @param assets The amount of collateral to supply
    /// @param onBehalf The address that owns the resulting position
    /// @param data Arbitrary callback data (empty for a plain supply)
    function supplyCollateral(
        MarketParams calldata marketParams,
        uint256 assets,
        address onBehalf,
        bytes calldata data
    ) external;

    /// @notice Borrows against the collateral of `onBehalf`
    /// @dev The caller must be authorized by `onBehalf` via setAuthorization;
    /// reverts if the resulting position is not healthy under the market lltv
    /// @param marketParams The market to borrow from
    /// @param assets The exact loan amount to borrow (shares must be 0)
    /// @param shares The borrow shares to mint (assets must be 0)
    /// @param onBehalf The address that owes the resulting debt
    /// @param receiver The recipient of the borrowed tokens
    /// @return assetsBorrowed The loan amount transferred to the receiver
    /// @return sharesBorrowed The borrow shares minted to `onBehalf`
    function borrow(
        MarketParams calldata marketParams,
        uint256 assets,
        uint256 shares,
        address onBehalf,
        address receiver
    ) external returns (uint256 assetsBorrowed, uint256 sharesBorrowed);

    /// @notice Authorizes or revokes `authorized` to manage the caller's
    /// positions (borrow, withdraw, withdrawCollateral on their behalf)
    /// @param authorized The address to authorize or revoke
    /// @param newIsAuthorized True to authorize, false to revoke
    function setAuthorization(address authorized, bool newIsAuthorized) external;

    /// @notice Whether `authorized` may manage the positions of `authorizer`
    /// @param authorizer The position owner
    /// @param authorized The candidate manager
    function isAuthorized(
        address authorizer,
        address authorized
    ) external view returns (bool);

    /// @notice The position of `user` in the market identified by `id`
    /// @param id The market id (keccak256 of the abi-encoded MarketParams)
    /// @param user The position owner
    /// @return supplyShares The user's supply shares
    /// @return borrowShares The user's borrow shares
    /// @return collateral The user's collateral balance
    function position(
        bytes32 id,
        address user
    )
        external
        view
        returns (uint256 supplyShares, uint128 borrowShares, uint128 collateral);
}

/// @title IMorphoFlashLoanCallback
/// @notice Interface a Morpho Blue flash loan borrower must implement
interface IMorphoFlashLoanCallback {
    /// @notice Called by Morpho Blue with the flash-loaned tokens already
    /// transferred to the callee
    /// @param assets The flash-loaned amount, which Morpho pulls back via
    /// transferFrom after this call returns
    /// @param data The data passed to flashLoan
    function onMorphoFlashLoan(uint256 assets, bytes calldata data) external;
}

project/contracts/interfaces/IMultiplier.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.35;

import {MarketParams} from "./IMorpho.sol";

/// @title IMultiplier - Leveraged SLP Deposit Interface
/// @author Sivo
/// @notice Opens a leveraged SLP position in one transaction: flash loan the
/// stablecoin from Morpho Blue, buy SLP at the oracle price through the
/// UniswapHook, post the SLP as collateral on Morpho on behalf of the user,
/// and borrow the flash-loaned amount back to repay the loan. The user ends
/// up owning a Morpho position of `principal * leverage` SLP collateral
/// against `principal * (leverage - 1)` stablecoin debt.
/// @dev The user must have authorized this contract on Morpho
/// (setAuthorization) before calling multiply, because the debt is opened in
/// the user's name. Collateral is likewise held by Morpho in the user's name;
/// this contract never retains funds between transactions.
interface IMultiplier {
    /// @notice Emitted when a leveraged position is opened
    /// @param sender The user the position was opened for
    /// @param asset The stablecoin deposited and borrowed
    /// @param principal The user's own stablecoin contribution
    /// @param flashAssets The flash-loaned amount borrowed back on Morpho
    /// @param shares The SLP posted as collateral for the user
    event Multiply(
        address indexed sender,
        address indexed asset,
        uint256 principal,
        uint256 flashAssets,
        uint256 shares
    );

    /// @notice Emitted when the Morpho market for an asset is configured
    /// @param asset The stablecoin the market lends
    /// @param oracle The Morpho market oracle
    /// @param irm The Morpho interest rate model
    /// @param lltv The Morpho liquidation loan-to-value (WAD)
    event MultiplierMarketSet(
        address indexed asset,
        address oracle,
        address irm,
        uint256 lltv
    );

    /// @notice A zero address was provided where one is not allowed
    error MultiplierZeroAddress();

    /// @notice A zero principal or flash-loan amount was provided
    error MultiplierZeroAmount();

    /// @notice No Morpho market is configured for the asset
    /// @param asset The unconfigured asset
    error MultiplierMarketNotSet(address asset);

    /// @notice The market params do not lend `asset` against SLP collateral
    error MultiplierInvalidMarket();

    /// @notice The SLP received is below the caller's minimum
    /// @param shares The SLP amount the deposit produced
    /// @param minShares The caller's minimum acceptable SLP amount
    error MultiplierSlippage(uint256 shares, uint256 minShares);

    /// @notice The flash loan callback was not invoked by Morpho within a
    /// multiply call
    error MultiplierUnauthorizedCallback();

    /// @notice Opens a leveraged SLP position for the caller
    /// @dev Pulls `principal` from the caller (requires a prior ERC-20
    /// approval), flash loans `flashAssets`, deposits the sum into the
    /// UniswapHook at the oracle price, posts the minted SLP as the caller's
    /// Morpho collateral, and borrows `flashAssets` in the caller's name to
    /// repay the flash loan. Reverts if the caller has not authorized this
    /// contract on Morpho or if the resulting position violates the market
    /// lltv.
    /// @param asset The stablecoin to deposit and borrow (USDC or USDT)
    /// @param principal The caller's own stablecoin contribution
    /// @param flashAssets The extra stablecoin to flash loan and leave as
    /// debt; principal * (leverage - 1)
    /// @param minShares The minimum SLP the combined deposit must produce
    /// @return shares The SLP posted as the caller's collateral
    function multiply(
        address asset,
        uint256 principal,
        uint256 flashAssets,
        uint256 minShares
    ) external returns (uint256 shares);

    /// @notice The Morpho market used for an asset
    /// @param asset The stablecoin
    /// @return marketParams The configured market params (zeroed when unset)
    function marketOf(
        address asset
    ) external view returns (MarketParams memory marketParams);

    /// @notice The Morpho Blue singleton
    function morpho() external view returns (address);

    /// @notice The UniswapHook the stablecoin is deposited through
    function hook() external view returns (address);

    /// @notice The SLP token posted as collateral
    function slp() external view returns (address);
}

project/contracts/interfaces/IUniswapHoo.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.35;

/// @title IUniswapHook - Oracle-Priced Uniswap v4 Hook Interface
/// @author Sivo
/// @notice One hook contract serves both SLP pools (SLP/USDC and SLP/USDT).
/// Deposits swap a stablecoin for freshly minted SLP at the exact Chainlink
/// NAV price; exits go through an asynchronous FIFO withdrawal queue that is
/// filled by inbound deposits and operator replenishment, mirroring the
/// ERC-7540 request/claimable/claim lifecycle of the legacy Vault.
/// @dev The pools hold zero curve liquidity: every swap is fully absorbed by
/// the hook via BeforeSwapDelta custom accounting. Only the stable-to-SLP
/// direction is a swap; the SLP-to-stable direction reverts and must use
/// requestWithdraw instead. Queue views and claims aggregate per
/// (asset, controller) so requests stay fungible, like requestId 0 in the
/// legacy ERC-7540 vault.
interface IUniswapHook {
    /// @notice Emitted when a deposit swap clears at the oracle price
    /// @param sender The address that initiated the deposit or swap
    /// @param receiver The address receiving the minted SLP
    /// @param asset The stablecoin paid in
    /// @param assets The amount of stablecoin paid in
    /// @param shares The amount of SLP minted to the receiver
    event Deposit(
        address indexed sender,
        address indexed receiver,
        address indexed asset,
        uint256 assets,
        uint256 shares
    );

    /// @notice Emitted when a withdrawal request enters the queue
    /// @param controller The address that can claim or cancel the request
    /// @param asset The stablecoin the request redeems into
    /// @param requestId The queue position identifier of the request
    /// @param sender The address that submitted the request
    /// @param shares The amount of SLP queued
    event RedeemRequest(
        address indexed controller,
        address indexed asset,
        uint256 indexed requestId,
        address sender,
        uint256 shares
    );

    /// @notice Emitted when queued SLP is cancelled and returned
    /// @param controller The controller whose pending SLP was returned
    /// @param asset The stablecoin the cancelled request redeemed into
    /// @param sender The address that submitted the cancellation
    /// @param shares The amount of unfilled SLP returned
    event RedeemCancel(
        address indexed controller,
        address indexed asset,
        address sender,
        uint256 shares
    );

    /// @notice Emitted when queued SLP is filled at the current oracle price
    /// @param controller The controller whose request was filled
    /// @param asset The stablecoin reserved for the controller
    /// @param assets The stablecoin amount locked for claiming
    /// @param shares The amount of SLP burned by the fill
    event RedeemClaimable(
        address indexed controller,
        address indexed asset,
        uint256 assets,
        uint256 shares
    );

    /// @notice Emitted when a controller claims filled withdrawal proceeds
    /// @param sender The address that initiated the claim
    /// @param receiver The address the stablecoin was paid to
    /// @param asset The stablecoin paid out
    /// @param assets The amount of stablecoin paid out
    /// @param shares The amount of SLP that was burned when the claim was
    /// filled (0 here; shares are reported on RedeemClaimable)
    event Withdraw(
        address indexed sender,
        address indexed receiver,
        address indexed asset,
        uint256 assets,
        uint256 shares
    );

    /// @notice Emitted when an operator is set or unset for a controller
    /// @param controller The controller granting or revoking the approval
    /// @param operator The operator being approved or revoked
    /// @param approved True when the operator is approved
    event OperatorSet(
        address indexed controller,
        address indexed operator,
        bool approved
    );

    /// @notice Emitted when the operator replenishes stablecoin to fill the queue
    /// @param asset The stablecoin replenished
    /// @param sender The operator that provided the stablecoin
    /// @param assets The amount of stablecoin pulled in
    event UniswapHookReplenish(
        address indexed asset,
        address indexed sender,
        uint256 assets
    );

    /// @notice Emitted when free (unreserved) stablecoin is swept to Sivo
    /// @param asset The stablecoin swept
    /// @param to The recipient of the sweep
    /// @param assets The amount swept
    event UniswapHookSweep(
        address indexed asset,
        address indexed to,
        uint256 assets
    );

    /// @notice Emitted when the minimum withdrawal request size changes
    /// @param minRequestShares The new minimum SLP amount per request
    event UniswapHookMinRequestChange(uint256 minRequestShares);

    /// @notice A zero address was provided where one is not allowed
    error UniswapHookZeroAddress();

    /// @notice The asset is not one of the configured stablecoins
    /// @param asset The unsupported asset address
    error UniswapHookUnsupportedAsset(address asset);

    /// @notice A pool key not sanctioned by this hook attempted to initialize
    error UniswapHookUnsupportedPool();

    /// @notice The SLP token and the two stablecoins must be three distinct
    /// addresses
    error UniswapHookInvalidAssetConfig();

    /// @notice Liquidity can never be added to the oracle-priced pools
    error UniswapHookLiquidityNotAllowed();

    /// @notice Donations to the oracle-priced pools are not allowed
    error UniswapHookDonateNotAllowed();

    /// @notice SLP cannot be swapped back through the pool; exits must use
    /// the asynchronous withdrawal queue
    error UniswapHookExitViaQueue();

    /// @notice The withdrawal request is below the configured minimum size
    /// @param shares The requested SLP amount
    /// @param minRequestShares The configured minimum SLP amount
    error UniswapHookRequestTooSmall(uint256 shares, uint256 minRequestShares);

    /// @notice The controller has less unfilled SLP queued than requested
    /// @param shares The SLP amount requested for cancellation
    /// @param pending The controller's unfilled queued SLP
    error UniswapHookInsufficientPending(uint256 shares, uint256 pending);

    /// @notice The controller has no claimable stablecoin for the asset
    /// @param controller The controller attempting the claim
    /// @param asset The stablecoin being claimed
    error UniswapHookNothingToClaim(address controller, address asset);

    /// @notice The sender is neither the controller nor an approved operator
    /// @param sender The unauthorized sender
    /// @param controller The controller of the request
    error UniswapHookUnauthorizedSender(address sender, address controller);

    /// @notice A swap or deposit resolves to a zero input or output amount
    error UniswapHookZeroAmount();

    /// @notice Deposits a stablecoin and receives SLP at the oracle price
    /// @dev Convenience entrypoint equivalent to routing a swap through the
    /// pool: the hook pulls the stablecoin, executes the oracle-priced swap
    /// against the PoolManager, and delivers freshly minted SLP. Requires a
    /// prior ERC-20 approval of this contract. Blocked while paused or while
    /// the oracle price is out of range.
    /// @param asset The stablecoin to deposit (USDC or USDT)
    /// @param assets The amount of stablecoin to deposit
    /// @param receiver The recipient of the minted SLP
    /// @return shares The amount of SLP delivered
    function deposit(
        address asset,
        uint256 assets,
        address receiver
    ) external returns (uint256 shares);

    /// @notice Queues SLP for asynchronous redemption into a stablecoin
    /// @dev Pulls SLP into the hook (requires a prior SLP approval). No price
    /// is locked at request time; pricing happens when the request is filled.
    /// @param asset The stablecoin to redeem into (USDC or USDT)
    /// @param shares The amount of SLP to queue
    /// @return requestId The queue position identifier
    function requestWithdraw(
        address asset,
        uint256 shares
    ) external returns (uint256 requestId);

    /// @notice Cancels unfilled queued SLP and returns it to the caller
    /// @param asset The stablecoin queue to cancel from
    /// @param shares The amount of unfilled SLP to cancel
    function cancelWithdraw(address asset, uint256 shares) external;

    /// @notice Cancels unfilled queued SLP on behalf of a controller
    /// @dev The caller must be the controller or an approved operator; the
    /// SLP is returned to the controller
    /// @param asset The stablecoin queue to cancel from
    /// @param shares The amount of unfilled SLP to cancel
    /// @param controller The controller whose request is cancelled
    function cancelWithdraw(
        address asset,
        uint256 shares,
        address controller
    ) external;

    /// @notice Claims the caller's filled withdrawal proceeds
    /// @dev Pays out the full claimable balance. Not gated on oracle health:
    /// the price was locked when the request was filled.
    /// @param asset The stablecoin to claim
    /// @param receiver The recipient of the stablecoin
    /// @return assets The amount of stablecoin paid out
    function claimWithdraw(
        address asset,
        address receiver
    ) external returns (uint256 assets);

    /// @notice Claims filled withdrawal proceeds on behalf of a controller
    /// @dev The caller must be the controller or an approved operator
    /// @param asset The stablecoin to claim
    /// @param receiver The recipient of the stablecoin
    /// @param controller The controller whose proceeds are claimed
    /// @return assets The amount of stablecoin paid out
    function claimWithdraw(
        address asset,
        address receiver,
        address controller
    ) external returns (uint256 assets);

    /// @notice Fills the withdrawal queue from the hook's free stablecoin
    /// @dev Permissionless keeper entrypoint; requires an in-range oracle
    /// price because filling sets the redemption price
    /// @param asset The stablecoin queue to fill
    /// @param maxIterations The maximum number of requests to visit
    /// @return assets The amount of stablecoin locked for claims
    function fill(
        address asset,
        uint256 maxIterations
    ) external returns (uint256 assets);

    /// @notice Pulls stablecoin from the operator and fills the queue
    /// @param asset The stablecoin to replenish
    /// @param assets The amount of stablecoin to pull in
    /// @param maxIterations The maximum number of requests to visit
    function replenish(
        address asset,
        uint256 assets,
        uint256 maxIterations
    ) external;

    /// @notice Sweeps free (unreserved) stablecoin to Sivo for RWA deployment
    /// @dev Free balance is the hook's physical balance minus the stablecoin
    /// reserved for filled-but-unclaimed withdrawals; the reserve can never
    /// be swept
    /// @param asset The stablecoin to sweep
    /// @param to The recipient of the sweep
    /// @return assets The amount swept
    function sweep(address asset, address to) external returns (uint256 assets);

    /// @notice Approves or revokes an operator for the caller's requests
    /// @param operator The operator to approve or revoke
    /// @param approved True to approve, false to revoke
    /// @return success Always true
    function setOperator(
        address operator,
        bool approved
    ) external returns (bool success);

    /// @notice Whether an operator is approved for a controller
    /// @param controller The controller
    /// @param operator The candidate operator
    /// @return status True when the operator is approved
    function isOperator(
        address controller,
        address operator
    ) external view returns (bool status);

    /// @notice The controller's unfilled queued SLP for an asset
    /// @param asset The stablecoin queue
    /// @param controller The controller
    /// @return shares The unfilled SLP amount
    function pendingWithdraw(
        address asset,
        address controller
    ) external view returns (uint256 shares);

    /// @notice The controller's claimable stablecoin for an asset
    /// @param asset The stablecoin queue
    /// @param controller The controller
    /// @return assets The claimable stablecoin amount
    function claimableWithdraw(
        address asset,
        address controller
    ) external view returns (uint256 assets);

    /// @notice The maximum stablecoin amount a deposit can currently swap
    /// @dev Returns 0 while paused or while the oracle price is out of range
    /// @param asset The stablecoin to deposit
    /// @return assets The maximum deposit amount
    function maxDeposit(address asset) external view returns (uint256 assets);

    /// @notice Total unfilled SLP queued for an asset
    /// @param asset The stablecoin queue
    /// @return shares The total unfilled SLP
    function totalPendingShares(
        address asset
    ) external view returns (uint256 shares);

    /// @notice Total stablecoin reserved for filled-but-unclaimed withdrawals
    /// @param asset The stablecoin queue
    /// @return assets The total reserved stablecoin
    function totalClaimableAssets(
        address asset
    ) external view returns (uint256 assets);

    /// @notice The hook's free (sweepable) stablecoin balance
    /// @param asset The stablecoin
    /// @return assets The sweepable amount
    function sweepable(address asset) external view returns (uint256 assets);

    /// @notice The number of requests ever queued for an asset
    /// @param asset The stablecoin queue
    /// @return length The queue tail index
    function queueLength(address asset) external view returns (uint256 length);
}

project/contracts/Multiplier.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// Compatible with OpenZeppelin Contracts ^5.0.0
pragma solidity 0.8.35;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {AccessManagedUpgradeable} from "@openzeppelin/contracts-upgradeable/access/manager/AccessManagedUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {ReentrancyGuardTransient} from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {UniswapHookOptions} from "./UniswapHookOptions.sol";
import {IMorpho, IMorphoFlashLoanCallback, MarketParams} from "./interfaces/IMorpho.sol";
import {IMultiplier} from "./interfaces/IMultiplier.sol";
import {IUniswapHook} from "./interfaces/IUniswapHook.sol";

/// @title Multiplier - Leveraged SLP Deposits via Morpho Blue
/// @author Sivo
/// @notice Opens a leveraged SLP position in one transaction: flash loan the
/// stablecoin from Morpho Blue, buy SLP at the oracle price through the
/// UniswapHook, post the SLP as the user's Morpho collateral, and borrow the
/// flash-loaned amount back in the user's name to repay the loan. Morpho Blue
/// flash loans are fee-free, so the debt equals the flash-loaned amount
/// exactly.
/// @dev The position (collateral and debt) lives on Morpho under the user's
/// address; this contract is a stateless router that never retains funds
/// between transactions. Borrowing in the user's name requires the user to
/// have authorized this contract on Morpho via setAuthorization. Market
/// configuration is restricted through a central OpenZeppelin AccessManager.
/// @custom:security-contact security@sivo.com
contract Multiplier is
    Initializable,
    IMultiplier,
    IMorphoFlashLoanCallback,
    PausableUpgradeable,
    AccessManagedUpgradeable,
    ReentrancyGuardTransient,
    UUPSUpgradeable
{
    struct Options {
        address authority;
        address morpho;
        address hook;
    }

    /// @custom:storage-location erc7201:sivo.storage.Multiplier
    struct MultiplierStorage {
        address _morpho;
        address _hook;
        address _slp;
        mapping(address asset => MarketParams) _markets;
    }

    // keccak256(abi.encode(uint256(keccak256("sivo.storage.Multiplier")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant MultiplierStorageLocation =
        0x45f6d2a1017413c81cf8b7b8f2c652f799011ae8b82a7d59b44de454fc11e900;

    /// @dev Transient slot holding keccak256 of the in-flight flash loan
    /// data; doubles as the "a multiply is in progress" marker that gates
    /// onMorphoFlashLoan
    // keccak256("sivo.transient.Multiplier.flashTag")
    bytes32 private constant FlashTagSlot =
        0xe777d3fd9c3d6c08c0417f143d523f319c0c8613c1b03e4de76a1f434ab35c2a;

    /// @dev Transient slot carrying the minted SLP amount out of the flash
    /// loan callback so multiply can return it
    // keccak256("sivo.transient.Multiplier.flashShares")
    bytes32 private constant FlashSharesSlot =
        0xcb177c6da10a7de8ef00e58cb3aeba1cf41bbce6aa7e63db392e34bb814e3e73;

    function _getMultiplierStorage()
        private
        pure
        returns (MultiplierStorage storage $)
    {
        assembly {
            $.slot := MultiplierStorageLocation
        }
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(Options memory options) public initializer {
        if (
            options.authority == address(0) ||
            options.morpho == address(0) ||
            options.hook == address(0)
        ) {
            revert MultiplierZeroAddress();
        }
        __Pausable_init();
        __AccessManaged_init(options.authority);
        MultiplierStorage storage $ = _getMultiplierStorage();
        $._morpho = options.morpho;
        $._hook = options.hook;
        // The collateral token is dictated by the hook, not configuration
        $._slp = UniswapHookOptions(options.hook).slp();
    }

    /// @inheritdoc IMultiplier
    function multiply(
        address asset,
        uint256 principal,
        uint256 flashAssets,
        uint256 minShares
    ) external nonReentrant whenNotPaused returns (uint256 shares) {
        MultiplierStorage storage $ = _getMultiplierStorage();
        if ($._markets[asset].loanToken == address(0)) {
            revert MultiplierMarketNotSet(asset);
        }
        if (principal == 0 || flashAssets == 0) revert MultiplierZeroAmount();
        SafeERC20.safeTransferFrom(
            IERC20(asset),
            msg.sender,
            address(this),
            principal
        );
        bytes memory data = abi.encode(msg.sender, asset, principal, minShares);
        bytes32 tag = keccak256(data);
        assembly {
            tstore(FlashTagSlot, tag)
        }
        IMorpho($._morpho).flashLoan(asset, flashAssets, data);
        assembly {
            shares := tload(FlashSharesSlot)
            tstore(FlashSharesSlot, 0)
        }
    }

    /// @notice Morpho Blue flash loan callback: buys SLP with the combined
    /// principal + flash-loaned stablecoin, posts it as the user's collateral,
    /// and borrows the flash-loaned amount back in the user's name so Morpho
    /// can pull the repayment after this call returns
    /// @dev Only callable by Morpho, and only while a multiply initiated by
    /// this contract is in flight (the transient tag binds the callback to
    /// the exact data multiply encoded)
    function onMorphoFlashLoan(uint256 assets, bytes calldata data) external {
        MultiplierStorage storage $ = _getMultiplierStorage();
        bytes32 tag;
        assembly {
            tag := tload(FlashTagSlot)
        }
        if (
            msg.sender != $._morpho ||
            tag == bytes32(0) ||
            tag != keccak256(data)
        ) {
            revert MultiplierUnauthorizedCallback();
        }
        assembly {
            tstore(FlashTagSlot, 0)
        }
        (address user, address asset, uint256 principal, uint256 minShares) =
            abi.decode(data, (address, address, uint256, uint256));
        MarketParams memory market = $._markets[asset];

        uint256 total = principal + assets;
        SafeERC20.forceApprove(IERC20(asset), $._hook, total);
        uint256 shares = IUniswapHook($._hook).deposit(
            asset,
            total,
            address(this)
        );
        if (shares < minShares) revert MultiplierSlippage(shares, minShares);

        SafeERC20.forceApprove(IERC20($._slp), $._morpho, shares);
        IMorpho($._morpho).supplyCollateral(market, shares, user, "");
        // Reverts unless the user authorized this contract and the position
        // stays healthy under the market lltv
        IMorpho($._morpho).borrow(market, assets, 0, user, address(this));
        // Morpho pulls the repayment via transferFrom after this returns
        SafeERC20.forceApprove(IERC20(asset), $._morpho, assets);

        assembly {
            tstore(FlashSharesSlot, shares)
        }
        emit Multiply(user, asset, principal, assets, shares);
    }

    /// @notice Configures the Morpho market leveraged deposits in `asset` use
    /// @dev Restricted through the AccessManager. The market must lend the
    /// asset against SLP collateral; oracle, irm, and lltv identify the
    /// specific Morpho market (its id is keccak256 of the full params).
    /// @param asset The stablecoin the market lends
    /// @param market The full Morpho market params
    function setMarket(
        address asset,
        MarketParams calldata market
    ) external restricted {
        MultiplierStorage storage $ = _getMultiplierStorage();
        if (
            asset == address(0) ||
            market.loanToken != asset ||
            market.collateralToken != $._slp
        ) {
            revert MultiplierInvalidMarket();
        }
        $._markets[asset] = market;
        emit MultiplierMarketSet(asset, market.oracle, market.irm, market.lltv);
    }

    /// @notice Pauses leveraged deposits
    /// @dev Restricted through the AccessManager
    function pause() external restricted {
        _pause();
    }

    /// @notice Unpauses leveraged deposits
    /// @dev Restricted through the AccessManager
    function unpause() external restricted {
        _unpause();
    }

    function _authorizeUpgrade(
        address newImplementation
    ) internal override restricted {}

    /// @inheritdoc IMultiplier
    function marketOf(
        address asset
    ) external view returns (MarketParams memory) {
        return _getMultiplierStorage()._markets[asset];
    }

    /// @inheritdoc IMultiplier
    function morpho() external view returns (address) {
        return _getMultiplierStorage()._morpho;
    }

    /// @inheritdoc IMultiplier
    function hook() external view returns (address) {
        return _getMultiplierStorage()._hook;
    }

    /// @inheritdoc IMultiplier
    function slp() external view returns (address) {
        return _getMultiplierStorage()._slp;
    }
}

